<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  [hidden] { display: none !important; }

  body {
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    margin: 0;
    padding: 24px 16px 60px;
    background: #f4f5f7;
    color: #20242a;
    line-height: 1.45;
  }
  .wrap { max-width: 720px; margin: 0 auto; }
  h1 { font-size: 1.5rem; margin: 0 0 18px; }
  h2 {
    font-size: .78rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: #6a737d;
    margin: 0 0 12px;
  }
  section {
    background: #fff;
    border: 1px solid #d9dde2;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 16px;
  }

  label { display: block; font-size: .82rem; font-weight: 600; margin-bottom: 4px; }
  input, select, button {
    font: inherit;
    color: inherit;
    background: #fff;
    border: 1px solid #c4cad1;
    border-radius: 7px;
    padding: 8px 10px;
  }
  input:focus, select:focus, button:focus {
    outline: 2px solid #1f6feb;
    outline-offset: 1px;
    border-color: #1f6feb;
  }
  .field { display: flex; flex-direction: column; min-width: 0; }

  /* ---- entry form ---- */
  .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 14px; }
  .form-grid .full { grid-column: 1 / -1; }
  #add-expense {
    background: #1f6feb;
    border-color: #1f6feb;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
    padding: 9px 18px;
  }
  #add-expense:hover { background: #1a5fd0; }
  #form-error {
    color: #b3261e;
    font-size: .9rem;
    margin: 8px 0 0;
    min-height: 1.3em;
  }

  /* ---- filters ---- */
  .filters { display: flex; flex-wrap: wrap; gap: 12px 14px; align-items: end; }
  .filters .field { flex: 1 1 150px; }
  #clear-filters { cursor: pointer; padding: 8px 14px; background: #f0f2f5; }
  #clear-filters:hover { background: #e6e9ee; }

  /* ---- summary ---- */
  .total-line {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    border-bottom: 1px solid #e4e7eb;
    padding-bottom: 10px;
  }
  .total-line .label { font-size: .95rem; color: #4a5158; }
  #total { font-size: 1.45rem; font-weight: 700; font-variant-numeric: tabular-nums; }
  .cat-rows {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 4px 28px;
    margin-top: 12px;
  }
  .cat-row {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 5px 0;
    border-bottom: 1px dashed #e4e7eb;
    font-size: .93rem;
  }
  .cat-row .cat-label { color: #4a5158; }
  .cat-total { font-weight: 600; font-variant-numeric: tabular-nums; }

  /* ---- list ---- */
  #list-head { display: flex; justify-content: space-between; align-items: baseline; }
  #visible-count { font-size: .85rem; color: #6a737d; }
  #expense-list { list-style: none; margin: 0; padding: 0; }
  .expense {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 2px;
    border-bottom: 1px solid #e4e7eb;
  }
  .expense:last-child { border-bottom: 0; }
  .exp-left { display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1; }
  .exp-category {
    font-size: .78rem;
    font-weight: 600;
    background: #eef2f7;
    border: 1px solid #dbe2ea;
    color: #3d4854;
    padding: 2px 9px;
    border-radius: 999px;
    white-space: nowrap;
  }
  .exp-note {
    color: #6a737d;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .exp-right { display: flex; align-items: center; gap: 14px; white-space: nowrap; }
  .exp-date { color: #6a737d; font-size: .9rem; font-variant-numeric: tabular-nums; }
  .exp-amount {
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    min-width: 4.5em;
    text-align: right;
  }
  .exp-del {
    cursor: pointer;
    font-size: .82rem;
    padding: 5px 10px;
    background: #fff;
    border: 1px solid #d9a19e;
    color: #b3261e;
    border-radius: 7px;
  }
  .exp-del:hover { background: #fbeae9; }
  #empty-message { color: #6a737d; text-align: center; padding: 18px 0 6px; margin: 0; }

  @media (max-width: 520px) {
    .form-grid { grid-template-columns: 1fr; }
    .exp-right { flex-wrap: wrap; justify-content: flex-end; }
  }
</style>
</head>
<body>
<div class="wrap">
  <h1>Expense Tracker</h1>

  <!-- ============ entry form ============ -->
  <section>
    <h2>Add expense</h2>
    <form id="expense-form" novalidate autocomplete="off">
      <div class="form-grid">
        <div class="field">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" min="0.01" placeholder="0.00">
        </div>
        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div class="field">
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div class="field">
          <label for="note">Note (optional)</label>
          <input type="text" id="note" maxlength="120" placeholder="e.g. weekly shop">
        </div>
        <div class="field full">
          <button type="submit" id="add-expense">Add expense</button>
        </div>
        <p id="form-error" class="full" role="alert"></p>
      </div>
    </form>
  </section>

  <!-- ============ filters ============ -->
  <section>
    <h2>Filters</h2>
    <div class="filters">
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field">
        <label for="filter-from">From date</label>
        <input type="date" id="filter-from">
      </div>
      <div class="field">
        <label for="filter-to">To date</label>
        <input type="date" id="filter-to">
      </div>
      <button type="button" id="clear-filters">Clear filters</button>
    </div>
  </section>

  <!-- ============ summary ============ -->
  <section>
    <h2>Summary</h2>
    <div class="total-line">
      <span class="label">Total (visible expenses)</span>
      <span id="total">0.00</span>
    </div>
    <div class="cat-rows" id="category-summary">
      <!-- one .cat-total[data-cat="..."] per category, filled by JS -->
    </div>
  </section>

  <!-- ============ list ============ -->
  <section>
    <div id="list-head">
      <h2>Expenses</h2>
      <span id="visible-count"></span>
    </div>
    <ul id="expense-list"></ul>
    <p id="empty-message" hidden>No expenses yet. Add your first expense above.</p>
  </section>
</div>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'expense-tracker.expenses';
  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

  var form = document.getElementById('expense-form');
  var amountInput = document.getElementById('amount');
  var categoryInput = document.getElementById('category');
  var dateInput = document.getElementById('date');
  var noteInput = document.getElementById('note');
  var formError = document.getElementById('form-error');

  var filterCategory = document.getElementById('filter-category');
  var filterFrom = document.getElementById('filter-from');
  var filterTo = document.getElementById('filter-to');
  var clearFiltersBtn = document.getElementById('clear-filters');

  var listEl = document.getElementById('expense-list');
  var emptyEl = document.getElementById('empty-message');
  var totalEl = document.getElementById('total');
  var catSummaryEl = document.getElementById('category-summary');
  var countEl = document.getElementById('visible-count');

  var expenses = load();

  /* ---------- persistence ---------- */

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data.filter(isValidExpense);
    } catch (err) {
      return [];
    }
  }

  function isValidExpense(e) {
    return e && typeof e === 'object' &&
      typeof e.id !== 'undefined' && e.id !== null &&
      typeof e.amount === 'number' && isFinite(e.amount) && e.amount > 0 &&
      CATEGORIES.indexOf(e.category) !== -1 &&
      typeof e.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(e.date);
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) {
      /* storage unavailable — app keeps working in memory */
    }
  }

  function uid() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  }

  /* ---------- add expense ---------- */

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var raw = (amountInput.value || '').trim();
    if (raw === '') {
      formError.textContent = 'Please enter an amount.';
      return;
    }
    var amount = Number(raw);
    if (!isFinite(amount)) {
      formError.textContent = 'Amount must be a valid number.';
      return;
    }
    if (amount <= 0) {
      formError.textContent = 'Amount must be greater than zero.';
      return;
    }
    var date = dateInput.value;
    if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date) || isNaN(new Date(date).getTime())) {
      formError.textContent = 'Please choose a date.';
      return;
    }
    var category = categoryInput.value;
    if (CATEGORIES.indexOf(category) === -1) {
      formError.textContent = 'Please choose a category.';
      return;
    }

    expenses.push({
      id: uid(),
      amount: Math.round(amount * 100) / 100,
      category: category,
      date: date,
      note: (noteInput.value || '').trim(),
      created: Date.now()
    });
    save();

    formError.textContent = '';
    amountInput.value = '';
    noteInput.value = '';
    amountInput.focus();

    render();
  });

  /* ---------- delete expense (event delegation, no confirm) ---------- */

  listEl.addEventListener('click', function (event) {
    var btn = event.target.closest ? event.target.closest('.exp-del') : null;
    if (!btn) return;
    var row = btn.closest('.expense');
    if (!row) return;
    var id = row.getAttribute('data-id');
    expenses = expenses.filter(function (e) { return String(e.id) !== id; });
    save();
    render();
  });

  /* ---------- filters ---------- */

  function passesFilters(exp) {
    var cat = filterCategory.value;
    var from = filterFrom.value;
    var to = filterTo.value;
    if (cat !== 'all' && exp.category !== cat) return false;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  [filterCategory, filterFrom, filterTo].forEach(function (el) {
    el.addEventListener('change', render);
    el.addEventListener('input', render);
  });

  clearFiltersBtn.addEventListener('click', function () {
    filterCategory.value = 'all';
    filterFrom.value = '';
    filterTo.value = '';
    render();
  });

  /* ---------- rendering ---------- */

  function render() {
    var visible = expenses.filter(passesFilters);

    // newest first: latest date first, most recently added breaks ties
    var sorted = visible.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return (b.created || 0) - (a.created || 0);
    });

    listEl.innerHTML = '';
    for (var i = 0; i < sorted.length; i++) {
      listEl.appendChild(buildRow(sorted[i]));
    }

    if (sorted.length === 0) {
      emptyEl.hidden = false;
      emptyEl.textContent = expenses.length === 0
        ? 'No expenses yet. Add your first expense above.'
        : 'No expenses match the current filters.';
    } else {
      emptyEl.hidden = true;
    }

    countEl.textContent = 'Showing ' + sorted.length + ' of ' + expenses.length +
      (expenses.length === 1 ? ' expense' : ' expenses');

    // grand total of visible expenses
    var total = 0;
    for (var t = 0; t < visible.length; t++) total += visible[t].amount;
    totalEl.textContent = total.toFixed(2);

    // per-category totals of visible expenses
    catSummaryEl.innerHTML = '';
    CATEGORIES.forEach(function (cat) {
      var sum = 0;
      for (var c = 0; c < visible.length; c++) {
        if (visible[c].category === cat) sum += visible[c].amount;
      }
      var row = document.createElement('div');
      row.className = 'cat-row';

      var label = document.createElement('span');
      label.className = 'cat-label';
      label.textContent = cat;

      var val = document.createElement('span');
      val.className = 'cat-total';
      val.setAttribute('data-cat', cat);
      val.textContent = sum.toFixed(2);

      row.appendChild(label);
      row.appendChild(val);
      catSummaryEl.appendChild(row);
    });
  }

  function buildRow(exp) {
    var li = document.createElement('li');
    li.className = 'expense';
    li.setAttribute('data-id', exp.id);

    var left = document.createElement('div');
    left.className = 'exp-left';

    var cat = document.createElement('span');
    cat.className = 'exp-category';
    cat.textContent = exp.category;
    left.appendChild(cat);

    if (exp.note) {
      var note = document.createElement('span');
      note.className = 'exp-note';
      note.textContent = exp.note;
      left.appendChild(note);
    }

    var right = document.createElement('div');
    right.className = 'exp-right';

    var date = document.createElement('span');
    date.className = 'exp-date';
    date.textContent = exp.date;

    var amount = document.createElement('span');
    amount.className = 'exp-amount';
    amount.textContent = exp.amount.toFixed(2);

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'exp-del';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete expense');

    right.appendChild(date);
    right.appendChild(amount);
    right.appendChild(del);

    li.appendChild(left);
    li.appendChild(right);
    return li;
  }

  render();
})();
</script>
</body>
</html>
